import{initial}from'./seed.js';import{brief,matches,splitTags,safeUrl,analysisPrompt,validateState}from'./core.js';import{zip}from'./zip.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state;try{state=validateState(JSON.parse(localStorage.getItem('scholar-atlas-v1')))}catch{state=structuredClone(initial)}let view='library',selected=null,tab='papers',query='',filter='',edit=null;const content=$('#content');
const dbp=new Promise((res,rej)=>{let r=indexedDB.open('scholar-atlas-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('pdf');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});async function fileop(key,value){let db=await dbp;return new Promise((res,rej)=>{let t=db.transaction('pdf',value===undefined?'readonly':'readwrite'),s=t.objectStore('pdf'),r=value===undefined?s.get(key):value===null?s.delete(key):s.put(value,key);t.oncomplete=()=>res(r.result);t.onerror=()=>rej(t.error)})}
function save(){try{localStorage.setItem('scholar-atlas-v1',JSON.stringify(state))}catch{toast('無法儲存：瀏覽器空間不足，請先備份。');throw Error('Storage failed')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}function download(name,data,type='text/plain'){let u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}function id(){return crypto.randomUUID()}function slug(s){return s.replace(/[^\p{L}\p{N}_-]/gu,'-').slice(0,65)||'professor'}function link(u,text){let v=safeUrl(u);return v?`<a href="${esc(v)}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`:'<span class="hint">來源待補充</span>'}function current(){return state.professors.find(p=>p.id===selected)}
$('#interests').value=state.interests;$('#interests').onchange=e=>{state.interests=e.target.value;save();render()};document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;render()});$('#closeDialog').onclick=$('#cancel').onclick=()=>$('#editor').close();$('#backup').onclick=()=>{download('scholar-atlas-backup.json',JSON.stringify(state,null,2),'application/json');toast('JSON 備份已匯出；PDF 請使用教授資料夾 ZIP 備份。')};$('#restore').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('備份過大（上限 10 MB）');let s=validateState(JSON.parse(await f.text()));if(!confirm('以備份取代目前的教授與筆記？建議先下載現有備份。'))return;state=s;save();$('#interests').value=s.interests;selected=null;render();toast('已匯入。PDF 不包含於 JSON，需另行重新附加。')}catch(x){toast('匯入失敗：'+x.message)}finally{e.target.value=''}};
function render(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=selected?current()?.name:({library:'教授研究庫',compare:'研究契合比較',guide:'使用與專案規則'}[view]);if(selected&&current())return detail();if(view==='compare')return compare();if(view==='guide')return guide();library()}
function library(){let total=state.professors.reduce((a,p)=>a+p.papers.length,0),read=state.professors.reduce((a,p)=>a+p.papers.filter(x=>x.status==='已閱讀').length,0);content.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR NEXT RESEARCH CHAPTER</div><h1>找到值得深入的研究方向。</h1><p>以教授為起點，讓論文、研究脈絡與申請準備各就其位。</p></div><button class="primary" data-act="add-prof">＋ 新增教授</button></section><div class="stats"><div class="stat"><div class="stat-icon">▱</div><div><strong>${state.professors.length.toString().padStart(2,'0')}</strong><small>教授資料夾</small></div></div><div class="stat"><div class="stat-icon">▤</div><div><strong>${total.toString().padStart(2,'0')}</strong><small>已收錄論文</small></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${read.toString().padStart(2,'0')}</strong><small>完成閱讀</small></div></div></div><div class="toolbar"><input id="search" aria-label="搜尋教授或研究方向" placeholder="⌕  搜尋教授、學校或研究方向" value="${esc(query)}"><select id="filter" aria-label="篩選研究狀態"><option value="">所有研究狀態</option>${['待研究','閱讀中','準備聯絡','已聯絡'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><span class="count">RESEARCH COLLECTION</span></div><div class="grid" id="cards"></div><div class="notice"><b>先收集證據，再形成判斷。</b>　範例收錄 Yoshua Bengio 的三篇共同著作，僅示範 GFlowNet 研究線索，不代表完整或最新研究範圍。新增自己的教授後，即可開始建立申請研究庫。</div>`;cards();$('#search').oninput=e=>{query=e.target.value;cards()};$('#filter').onchange=e=>{filter=e.target.value;cards()}}
function cards(){let ps=state.professors.filter(p=>(!filter||p.status===filter)&&[p.name,p.school,p.program,...p.papers.map(x=>x.tags)].join(' ').toLowerCase().includes(query.toLowerCase()));$('#cards').innerHTML=ps.map(p=>{let tags=[...new Set(p.papers.flatMap(x=>splitTags(x.tags)))].slice(0,3);return`<article class="card"><div class="card-top"><div class="avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><span class="badge green">${esc(p.status)}</span></div><h2>${esc(p.name)}</h2><div class="school">${esc(p.school)} · ${esc(p.program)}</div><div class="tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'<span class="tag">等待加入論文</span>'}</div><p>${esc(p.note.split('\n')[0].slice(0,95)||'尚未建立研究概要。加入論文與閱讀筆記，逐步整理研究方向。')}</p><div class="card-bottom"><span>▤ ${p.papers.length} 篇論文</span><button data-act="open" data-id="${esc(p.id)}">開啟資料夾 →</button></div></article>`}).join('')+`<button class="card add-card" data-act="add-prof"><span class="plus">＋</span><h3>下一位研究夥伴</h3><p>建立教授資料夾<br>開始探索新的研究可能</p></button>`}
function detail(){let p=current();content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="back">← 教授研究庫</a></div><h1>${esc(p.name)}</h1><p>${esc(p.school)} · ${esc(p.program)}　${link(p.url,'教授研究頁面')}</p></div><div class="actions"><button data-act="edit-prof">編輯教授</button><button data-act="zip">↓ 匯出資料夾</button><button class="primary" data-act="add-paper">＋ 新增論文</button></div></section><div class="tabs">${[['papers','論文資料夾'],['overview','研究概要'],['notes','申請準備'],['ai','AI 分析包']].map(([k,n])=>`<button data-act="tab" data-id="${k}" class="${tab===k?'selected':''}">${n}</button>`).join('')}</div><div id="detailBody"></div>`;let d=$('#detailBody');if(tab==='papers'){d.innerHTML=`<div class="panel"><div class="actions" style="justify-content:space-between"><h2>論文與閱讀筆記 <span class="badge">${p.papers.length} PAPERS</span></h2><span class="hint">由新到舊 · 年份以收錄版本為準</span></div>${[...p.papers].sort((a,b)=>b.year-a.year).map(x=>`<article class="paper"><div class="year">${x.year}</div><div><h3>${esc(x.title)}</h3><span class="badge">${esc(x.level)}</span> <span class="badge green">${esc(x.status)}</span><p>${esc(x.abstract||'尚未提供摘要。')}</p><div class="tags">${splitTags(x.tags).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><span class="source">${link(x.url,'來源論文')}</span></div><div class="actions"><button data-act="edit-paper" data-id="${esc(x.id)}">筆記／編輯</button>${x.pdf?`<button data-act="pdf" data-id="${esc(x.id)}">開啟 PDF</button>`:''}</div></article>`).join('')||'<div class="empty">還沒有論文。新增標題、來源與摘要，或附上自己的 PDF。</div>'}</div><p class="hint">PDF 保存在本機瀏覽器。第一版不自動擷取 PDF 內文，請貼上摘要或已讀段落供概要整理。</p><button class="danger" data-act="delete-prof">刪除此教授資料夾</button>`}else if(tab==='overview'){d.innerHTML=`<div class="notice"><b>有來源的結構化概要</b>　依現有欄位彙整，非即時 LLM 生成。資料不足會明確標示；新增論文後即時更新。</div><div class="actions"><button data-act="brief">↓ 下載研究概要 .md</button><button data-act="tab" data-id="ai">準備深入 AI 分析 →</button></div><div class="panel overview">${esc(brief(p,state.interests))}</div>`}else if(tab==='notes'){d.innerHTML=`<div class="two-col"><section class="panel"><h2>研究綜合筆記與聯絡準備</h2><p>可貼上核對後的 AI 分析；保留 [論文ID] 引用，並寫下自己的問題與經驗。</p><textarea id="notes" style="min-height:340px" aria-label="研究綜合筆記">${esc(p.note)}</textarea><button class="primary" style="margin-top:14px" data-act="save-notes">儲存研究筆記</button></section><section class="panel"><div class="eyebrow">BEFORE YOU REACH OUT</div><h2>讓聯絡信有研究依據</h2><ol><li>指出一篇你確實閱讀過的論文與具體方法。</li><li>說明它與你的研究經驗如何連接。</li><li>提出一個可討論的問題，而非籠統稱讚。</li><li>查核官方頁面的現職與招生資訊。</li></ol><h3>目前的字面興趣交集</h3><div class="tags">${matches(p,state.interests).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'尚未找到關鍵字交集'}</div><p>這是閱讀線索，不是研究契合度或錄取機率評分。系統不會自動寄出聯絡信。</p></section></div>`}else{d.innerHTML=`<div class="panel"><div class="eyebrow">EVIDENCE → SYNTHESIS</div><h2>把整個教授資料夾交給 AI 閱讀</h2><p>1. 複製或下載分析包。 2. 貼到 ChatGPT／Claude，並按需要附上 PDF。 3. 核對引用與結論，保存到「申請準備」。<br>分析包包含論文摘要與筆記，不包含 PDF 內文；本網站沒有內建付費 API 或自動網路搜尋。</p><div class="actions"><button class="primary" data-act="copy-prompt">複製 AI 分析包</button><button data-act="prompt">↓ 下載分析包</button></div><textarea id="promptText" aria-label="AI 分析提示詞" style="min-height:350px;margin-top:20px" readonly>${esc(analysisPrompt(p,state.interests))}</textarea></div>`}}
function compare(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">COMPARE WITH EVIDENCE</div><h1>比較方向，而非比較光環。</h1><p>只比較你的研究庫已收錄的資料。缺漏不等於不契合。</p></div></section><div class="panel table-scroll"><table><thead><tr><th>教授／學校</th><th>研究標籤</th><th>我的興趣交集</th><th>資料涵蓋</th><th>閱讀進度</th></tr></thead><tbody>${state.professors.map(p=>`<tr><td><a href="#" data-act="open" data-id="${esc(p.id)}">${esc(p.name)}</a><br>${esc(p.school)}</td><td>${esc([...new Set(p.papers.flatMap(x=>splitTags(x.tags)))].join('、'))||'待補充'}</td><td>${esc(matches(p,state.interests).join('、'))||'尚無字面交集'}</td><td>${p.papers.length} 篇<br>${p.papers.length?Math.min(...p.papers.map(x=>x.year))+'–'+Math.max(...p.papers.map(x=>x.year)):'尚無資料'}</td><td>${p.papers.filter(x=>x.status==='已閱讀').length} / ${p.papers.length}<div class="progress"><span style="width:${p.papers.length?p.papers.filter(x=>x.status==='已閱讀').length/p.papers.length*100:0}%"></span></div></td></tr>`).join('')}</tbody></table></div><div class="notice">關鍵字比對不理解同義詞；請用 AI 分析包深入比對研究問題、方法、限制與自己的經驗。收錄資料不代表完整著作或目前招生方向。</div>`}
function guide(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">A REUSABLE RESEARCH WORKFLOW</div><h1>一套可以繼續長大的研究庫。</h1><p>本專案以 AGENTS.md 定義資料規格、證據規則與開發方式。</p></div></section><div class="panel"><h2>開始使用</h2><ol><li>新增教授，填寫學校、program 與官方頁面。</li><li>加入論文，確認教授是作者之一；以發表版本填年份。</li><li>貼上摘要、方法、成果與限制，附上來源連結，可附加 PDF。</li><li>查看研究概要與研究契合比較，下載 AI 分析包進一步整理。</li><li>把核對後的概要存到申請準備，匯出教授 ZIP 資料夾。</li></ol><p>PDF 單檔上限 20 MB，存在 IndexedDB；教授、論文欄位和筆記保存在 localStorage。更換瀏覽器或清除網站資料可能遺失資料。JSON 備份不含 PDF；教授 ZIP 包含本機仍存在的 PDF。</p></div><div class="panel"><h2>開發與作業文件</h2><div class="doclinks"><a href="AGENTS.md" download>AGENTS.md ↓</a><a href="README.md" download>README.md ↓</a><a href="SUBMISSION.md" download>作業繳交說明 ↓</a><a href="scholar-atlas-source.zip" download>完整 GitHub 專案 ZIP ↓</a></div><p>新增教授使用相同資料格式；新增分析頁面重用論文資料與共用安全函式。範例已附來源，使用者匯入內容仍需自行查核。</p></div><div class="panel"><h2>目前功能範圍</h2><p>可用：教授分類、論文與 PDF 保存、閱讀筆記、結構化概要、研究比較、AI 分析包、備份和資料夾匯出。<br>尚未串接：自動搜尋全部教授、自動下載付費論文、PDF 文字擷取、網站內即時 LLM 分析、跨裝置同步。</p></div>`}
const input=(n,label,v='',type='text',required=false)=>`<label class="field">${label}<input name="${n}" type="${type}" value="${esc(v)}" ${required?'required':''} ${type==='number'?'min="1900" max="2200"':''}></label>`;const area=(n,label,v='')=>`<label class="field">${label}<textarea name="${n}">${esc(v)}</textarea></label>`;const select=(n,label,v,opts)=>`<label class="field">${label}<select name="${n}">${opts.map(s=>`<option ${s===v?'selected':''}>${s}</option>`).join('')}</select></label>`;
function editor(kind,obj){edit={kind,id:obj?.id};let x=obj||{};$('#dialogTitle').textContent=(obj?'編輯':'新增')+(kind==='prof'?'教授資料夾':'論文與筆記');$('#fields').innerHTML=kind==='prof'?input('name','教授姓名 *',x.name,'text',true)+`<div class="form-grid">${input('school','學校',x.school)}${input('program','Program／系所',x.program)}</div>`+input('url','官方研究頁面（https://）',x.url,'url')+select('status','研究進度',x.status,['待研究','閱讀中','準備聯絡','已聯絡'])+area('note','初步研究筆記',x.note):input('title','論文標題 *',x.title,'text',true)+`<div class="form-grid">${input('year','版本年份 *',x.year||new Date().getFullYear(),'number',true)}${select('status','閱讀狀態',x.status,['待閱讀','閱讀中','已閱讀'])}</div>`+input('url','論文來源（DOI／arXiv／出版頁）',x.url,'url')+input('tags','研究標籤（逗號分隔）',x.tags)+select('level','資料閱讀層級',x.level,['摘要／書目','全文閱讀','使用者筆記'])+area('abstract','摘要／研究問題（貼上可用於 AI 分析的文字）',x.abstract)+area('method','研究方法',x.method)+area('finding','主要成果（保留來源位置）',x.finding)+area('limitation','限制／尚待查證之處',x.limitation)+`<label class="field">附加 PDF（可選，20 MB 以下；不自動解析）<input name="pdfFile" type="file" accept="application/pdf,.pdf"></label>${x.pdf?'<p class="hint">已附加 PDF，未選擇新檔案時保留。</p>':''}${x.id?`<button type="button" class="danger" style="margin-top:20px" data-act="delete-paper" data-id="${esc(x.id)}">刪除此論文</button>`:''}`;$('#editor').showModal()}
$('#editForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),obj=Object.fromEntries(f),p=current();try{if(edit.kind==='prof'){obj.id=edit.id||id();obj.name=obj.name.trim();if(!obj.name)throw Error('請輸入姓名');if(obj.url&&!safeUrl(obj.url))throw Error('來源網址必須為 HTTP 或 HTTPS');obj.papers=edit.id?state.professors.find(x=>x.id===edit.id).papers:[];if(edit.id)Object.assign(state.professors.find(x=>x.id===edit.id),obj);else state.professors.push(obj)}else{let old=p.papers.find(x=>x.id===edit.id),file=f.get('pdfFile');delete obj.pdfFile;obj.id=edit.id||id();obj.title=obj.title.trim();if(!obj.title)throw Error('請輸入標題');obj.year=Number(obj.year);if(!Number.isInteger(obj.year)||obj.year<1900||obj.year>2200)throw Error('年份無效');if(obj.url&&!safeUrl(obj.url))throw Error('來源網址必須為 HTTP 或 HTTPS');if(p.papers.some(x=>x.id!==obj.id&&(x.title.toLowerCase()===obj.title.toLowerCase()||(obj.url&&x.url===obj.url))))throw Error('這篇論文已在此教授資料夾中');if(old?.pdf)obj.pdf=old.pdf;if(file?.size){if(file.size>20*1024*1024)throw Error('PDF 超過 20 MB');if(new TextDecoder().decode(await file.slice(0,5).arrayBuffer())!=='%PDF-')throw Error('檔案不是有效 PDF');await fileop(p.id+'/'+obj.id,file);obj.pdf=file.name}if(old)Object.assign(old,obj);else p.papers.push(obj)}save();$('#editor').close();render();toast('已儲存到本機工作區')}catch(x){toast(x.message)}};
async function exportFolder(){let p=current(),root=slug(p.name),entries=[[root+'/profile.json',JSON.stringify({...p,papers:undefined},null,2)],[root+'/overview.md',brief(p,state.interests)],[root+'/application-notes.md',p.note],[root+'/ai-analysis-prompt.txt',analysisPrompt(p,state.interests)]];let missing=0;for(let q of p.papers){let folder=root+'/papers/'+q.year+'-'+slug(q.title)+'-'+q.id.slice(0,8);entries.push([folder+'/paper.json',JSON.stringify(q,null,2)]);if(q.pdf){let f=await fileop(p.id+'/'+q.id);if(f)entries.push([folder+'/paper.pdf',f]);else missing++}}if(missing)entries.push([root+'/MISSING_FILES.txt',`${missing} 個 PDF 在目前瀏覽器不存在，請重新附加。`]);download(root+'.zip',await zip(entries));toast(missing?`已匯出，但 ${missing} 個 PDF 缺失；詳見 ZIP 內說明。`:'已匯出教授資料夾，包含可用的 PDF 與概要。')}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();let a=b.dataset.act,k=b.dataset.id,p=current();try{if(a==='add-prof')editor('prof');if(a==='edit-prof')editor('prof',p);if(a==='open'){selected=k;view='library';tab='papers';render()}if(a==='back'){selected=null;render()}if(a==='tab'){tab=k;detail()}if(a==='add-paper')editor('paper');if(a==='edit-paper')editor('paper',p.papers.find(x=>x.id===k));if(a==='save-notes'){p.note=$('#notes').value;save();toast('研究筆記已儲存')}if(a==='brief')download(slug(p.name)+'-overview.md',brief(p,state.interests));if(a==='prompt')download(slug(p.name)+'-ai-analysis.txt',analysisPrompt(p,state.interests));if(a==='copy-prompt'){try{await navigator.clipboard.writeText(analysisPrompt(p,state.interests));toast('分析包已複製')}catch{$('#promptText').select();toast('請使用 Ctrl+C／⌘C 複製選取的分析包')}}if(a==='pdf'){let f=await fileop(p.id+'/'+k);if(f)download(p.papers.find(x=>x.id===k).pdf,f);else toast('此瀏覽器找不到 PDF，請重新附加。')}if(a==='zip')await exportFolder();if(a==='delete-paper'&&confirm('刪除此論文與其本機 PDF？')){await fileop(p.id+'/'+k,null);p.papers=p.papers.filter(x=>x.id!==k);save();$('#editor').close();render()}if(a==='delete-prof'&&confirm('刪除整個教授資料夾及本機 PDF？請先備份。')){for(let q of p.papers)await fileop(p.id+'/'+q.id,null);state.professors=state.professors.filter(x=>x.id!==p.id);selected=null;save();render()}}catch(x){toast('操作失敗：'+x.message)}});render();
